// Merge sort: partir a la mitad, ordenar cada mitad y mezclar las dos ya ordenadas
let comparaciones = 0;

function mezclar(izq, der) {                         // izq y der YA vienen ordenadas
  const salida = [];
  let i = 0, j = 0;
  while (i < izq.length && j < der.length) {
    comparaciones++;
    if (der[j] < izq[i]) salida.push(der[j++]);      // pasa el menor de los dos que están al frente
    else salida.push(izq[i++]);                       // si empatan, pasa el de la izquierda (eso lo hace estable)
  }
  return salida.concat(izq.slice(i), der.slice(j));   // lo que sobre ya está ordenado
}

function mergeSort(lista, nivel = 0) {
  const sangria = "  ".repeat(nivel);
  if (lista.length <= 1) return lista;               // 0 o 1 elemento: ya está ordenada
  const medio = Math.floor(lista.length / 2);
  console.log(sangria + "partir   " + JSON.stringify(lista));
  const izq = mergeSort(lista.slice(0, medio), nivel + 1);
  const der = mergeSort(lista.slice(medio), nivel + 1);
  const resultado = mezclar(izq, der);
  console.log(sangria + "mezclar  " + JSON.stringify(izq) + " + " + JSON.stringify(der) + " -> " + JSON.stringify(resultado));
  return resultado;
}

