console.log("comparaciones:", comparaciones);

// Contamos comparaciones: es la unidad de costo de un ordenamiento por comparación
let comparaciones = 0;
const menor = (a, b) => { comparaciones++; return a < b; };

function mezclar(izq, der) {
  const r = []; let i = 0, j = 0;
  while (i < izq.length && j < der.length) r.push(menor(der[j], izq[i]) ? der[j++] : izq[i++]);
  return r.concat(izq.slice(i), der.slice(j));
}
function mergeSort(v) {
  if (v.length <= 1) return v;
  const m = v.length >> 1;
  return mezclar(mergeSort(v.slice(0, m)), mergeSort(v.slice(m)));
}

// Números al azar con semilla fija: tu corrida da lo mismo que la mía
let estado = 42;
const azar = () => { estado = (Math.imul(estado, 1664525) + 1013904223) >>> 0; return estado / 2 ** 32; };

function quicksort(v, pivotePorAzar) {
  const a = v.slice();
  function ordenar(desde, hasta) {
    while (desde < hasta) {
      const p = pivotePorAzar ? desde + Math.floor(azar() * (hasta - desde + 1)) : hasta;
      [a[p], a[hasta]] = [a[hasta], a[p]];             // el pivote se guarda al final
      const pivote = a[hasta];
      let borde = desde;                                // todo lo anterior a «borde» es menor que el pivote
      for (let i = desde; i < hasta; i++) {
        if (menor(a[i], pivote)) { [a[i], a[borde]] = [a[borde], a[i]]; borde++; }
      }
      [a[borde], a[hasta]] = [a[hasta], a[borde]];      // el pivote queda en su lugar definitivo
      if (borde - desde < hasta - borde) { ordenar(desde, borde - 1); desde = borde + 1; }  // la parte chica, por llamada
      else { ordenar(borde + 1, hasta); hasta = borde - 1; }                                 // la grande, en este mismo bucle
    }
  }
  ordenar(0, a.length - 1);
  return a;
}

const n = 1000;
const entradas = {
  "al azar":       Array.from({ length: n }, () => Math.floor(azar() * 1e9)),
  "ya ordenada":   Array.from({ length: n }, (_, i) => i),
  "al revés":      Array.from({ length: n }, (_, i) => n - i),
  "todas iguales": Array(n).fill(7),
};
console.log("n =", n, "| n·log2(n) =", Math.round(n * Math.log2(n)), "| n·(n-1)/2 =", n * (n - 1) / 2);
for (const [nombre, v] of Object.entries(entradas)) {
  const fila = [];
  for (const [metodo, f] of [["merge sort", mergeSort], ["quick, pivote = último", w => quicksort(w, false)], ["quick, pivote al azar", w => quicksort(w, true)]]) {
    comparaciones = 0;
    const r = f(v);
    const ok = r.every((x, i) => i === 0 || r[i - 1] <= x);
    fila.push(metodo + ": " + comparaciones + (ok ? "" : " (¡mal ordenada!)"));
  }
  console.log(nombre.padEnd(14), fila.join(" | "));
}

// Entregas: id, zona y hora de pedido. Queremos agrupar por zona y, dentro de cada zona, por hora.
const pedidos = [
  { id: "A", zona: "Norte", hora: 9 },  { id: "B", zona: "Sur",   hora: 8 },
  { id: "C", zona: "Norte", hora: 8 },  { id: "D", zona: "Sur",   hora: 10 },
  { id: "E", zona: "Norte", hora: 10 }, { id: "F", zona: "Sur",   hora: 9 },
];
const mostrar = (titulo, lista) => console.log(titulo.padEnd(30), lista.map(p => p.id + p.zona[0] + p.hora).join("  "));

// Receta de dos pasadas: primero por hora, después por zona. Funciona solo si la segunda pasada es ESTABLE.
const porHora = [...pedidos].sort((a, b) => a.hora - b.hora);
mostrar("1) por hora:", porHora);
mostrar("2) luego por zona (estable):", [...porHora].sort((a, b) => a.zona.localeCompare(b.zona)));

// Un solo comparador con desempate: lo mismo en una pasada, sin depender de la estabilidad
mostrar("una pasada con desempate:", [...pedidos].sort((a, b) => a.zona.localeCompare(b.zona) || a.hora - b.hora));

// Selección intercambia a distancia y no es estable: la misma segunda pasada rompe el orden de las horas
function seleccion(lista, menor) {
  const a = [...lista];
  for (let i = 0; i < a.length - 1; i++) {
    let m = i;
    for (let j = i + 1; j < a.length; j++) if (menor(a[j], a[m])) m = j;
    [a[i], a[m]] = [a[m], a[i]];
  }
  return a;
}
mostrar("2) con selección (inestable):", seleccion(porHora, (a, b) => a.zona < b.zona));

