// El comparador que devuelve un número al azar rompe el contrato (a veces dice a < b y después b < a).
// Prueba: de 4 elementos, ¿con qué frecuencia el primero se queda en el primer lugar? Lo justo sería 25 %.
const conSort = lista => [...lista].sort(() => Math.random() - 0.5);
function fisherYates(lista) {                       // el método correcto: un intercambio por posición
  const r = [...lista];
  for (let i = r.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));  // un lugar al azar entre 0 e i
    [r[i], r[j]] = [r[j], r[i]];
  }
  return r;
}
function primeroSeQueda(mezclador, veces = 100000) {
  let cuantas = 0;
  for (let k = 0; k < veces; k++) if (mezclador([0, 1, 2, 3])[0] === 0) cuantas++;
  return (100 * cuantas / veces).toFixed(1) + " %";
}
console.log("sort + Math.random()     :", primeroSeQueda(conSort));
console.log("Fisher-Yates             :", primeroSeQueda(fisherYates));
